        self.val = val
        self.left = left
        self.right = right

class Solution:
    def isSubtree(self, root, subRoot):
        def ser(node):
            if not node: return ',#'
            return ',' + str(node.val) + ser(node.left) + ser(node.right)
        return ser(subRoot) in ser(root)

